tool_input.command:
cd src/data && node -e "
const fs=require('fs');let s=fs.readFileSync('products.ts','utf8');
const facts={'canvas-field-tote':'18 OZ CANVAS','waxed-day-pack':'22 L WAXED CANVAS','weekender-duffel':'45 L CAPACITY','merino-crew-sweater':'100% MERINO','heavyweight-pocket-tee':'240 GSM JERSEY','cotton-chore-coat':'COTTON TWILL','enamel-camp-mug':'350 ML ENAMEL','cast-iron-skillet':'PRE-SEASONED IRON','linen-tea-towels':'100% LINEN','leather-key-ring':'VEG-TANNED LEATHER','ribbed-wool-beanie':'WOOL BLEND'};
for(const [k,v] of Object.entries(facts)){ if(v.length>18) throw k; s=s.replace(new RegExp(\"(slug: '\"+k+\"',[\\\\s\\\\S]*?tone: '\\\\w+',)\"),'\$1\n    specFact: \''+v+'\',');}
s=s.replace('  tone: Tone;\n}','  tone: Tone;\n  /** One fact of at most 18 characters for the spec plate caption, e.g. \"18 OZ CANVAS\". */\n  specFact: string;\n}');
fs.writeFileSync('products.ts',s);" && grep -c specFact products.ts
